<?php declare(strict_types=1); session_start(); require_once __DIR__.'/../app/config/config.php'; requireLogin(); $page=$_GET['page']??'dashboard'; $rf=new RandomForestService(); if(!$pdo){render('dashboard/index',['dbError'=>$dbError??'Database error','stats'=>[],'recent'=>[]]);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??''; try{ if($action==='add_student'){ $pdo->prepare('INSERT INTO students(nis,name,gender,class_id,class_name,attendance_rate) VALUES(?,?,?,?,?,?)')->execute([trim($_POST['nis']),trim($_POST['name']),$_POST['gender'],(int)$_POST['class_id'],trim($_POST['class_name']),(float)$_POST['attendance_rate']]);flash('success','Siswa berhasil ditambahkan.');redirect('students'); } if($action==='delete_student'){ $pdo->prepare('DELETE FROM students WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Data siswa dihapus.');redirect('students'); } if($action==='add_assessment'){ $sid=(int)$_POST['student_id'];$k=(float)$_POST['knowledge_score'];$s=(float)$_POST['skill_score'];$ar=(float)$_POST['assignment_rate'];$pdo->prepare('INSERT INTO assessments(student_id,subject,knowledge_score,skill_score,assignment_rate,assessment_date,notes) VALUES(?,?,?,?,?,?,?)')->execute([$sid,trim($_POST['subject']),$k,$s,$ar,$_POST['assessment_date'],trim($_POST['notes'])]);$q=$pdo->prepare('SELECT attendance_rate FROM students WHERE id=?');$q->execute([$sid]);$att=(float)$q->fetchColumn();$p=$rf->predict(['avg_score'=>($k+$s)/2,'attendance'=>$att,'assignment_rate'=>$ar,'trend'=>0]);$aid=(int)$pdo->lastInsertId();$mat=$pdo->query("SELECT id FROM learning_materials ORDER BY id LIMIT 1")->fetchColumn();$pdo->prepare('INSERT INTO recommendations(student_id,assessment_id,action_label,material_id,confidence,explanation) VALUES(?,?,?,?,?,?)')->execute([$sid,$aid,$p['label'],$mat,$p['confidence'],$p['explanation']]);flash('success','Asesmen tersimpan dan rekomendasi AI dibuat.');redirect('assessments'); } if($action==='add_master'){if(($_POST['type']??'')==='subject'){$pdo->prepare('INSERT INTO subjects(name,code) VALUES(?,?)')->execute([trim($_POST['name']),trim($_POST['code'])]);$target='subjects';}else{$pdo->prepare('INSERT INTO classes(name,grade,homeroom_teacher) VALUES(?,?,?)')->execute([trim($_POST['name']),trim($_POST['grade']),trim($_POST['homeroom_teacher'])]);$target='classes';}flash('success','Data master berhasil ditambahkan.');redirect($target);} }catch(Throwable $e){flash('danger','Gagal: '.$e->getMessage());redirect($page);}}
if($page==='dashboard'){$stats=['students'=>(int)$pdo->query('SELECT COUNT(*) FROM students')->fetchColumn(),'assessments'=>(int)$pdo->query('SELECT COUNT(*) FROM assessments')->fetchColumn(),'remedial'=>(int)$pdo->query("SELECT COUNT(*) FROM recommendations WHERE action_label='Remedial'")->fetchColumn(),'mastery'=>(int)$pdo->query('SELECT COUNT(*) FROM (SELECT student_id FROM assessments GROUP BY student_id HAVING AVG((knowledge_score+skill_score)/2)>=75)x')->fetchColumn()];$recent=$pdo->query('SELECT a.*,s.name,s.class_name,(a.knowledge_score+a.skill_score)/2 avg_score FROM assessments a JOIN students s ON s.id=a.student_id ORDER BY a.id DESC LIMIT 6')->fetchAll();render('dashboard/index',compact('stats','recent'));exit;}
if($page==='students'){$students=$pdo->query('SELECT s.*,COALESCE(c.name,s.class_name) class_name FROM students s LEFT JOIN classes c ON c.id=s.class_id ORDER BY class_name,s.name')->fetchAll();$classes=$pdo->query('SELECT * FROM classes ORDER BY name')->fetchAll();render('students/index',compact('students','classes'));exit;}
if($page==='assessments'){$students=$pdo->query('SELECT id,name,class_name FROM students ORDER BY name')->fetchAll();$assessments=$pdo->query('SELECT a.*,s.name,s.class_name,(a.knowledge_score+a.skill_score)/2 avg_score,r.action_label,r.confidence FROM assessments a JOIN students s ON s.id=a.student_id LEFT JOIN recommendations r ON r.assessment_id=a.id ORDER BY a.id DESC')->fetchAll();render('assessments/index',compact('students','assessments'));exit;}
if($page==='reports'){$reportType=$_GET['type']??'summary';$reports=$pdo->query('SELECT s.id student_id,s.name,s.nis,s.class_name,s.attendance_rate,a.subject,a.assessment_date,(a.knowledge_score+a.skill_score)/2 avg_score,a.assignment_rate,r.action_label,r.confidence FROM students s JOIN assessments a ON a.student_id=s.id LEFT JOIN recommendations r ON r.assessment_id=a.id ORDER BY s.class_name,s.name')->fetchAll();render('reports/index',compact('reports','reportType'));exit;}
if($page==='recommendations'){$recommendations=$pdo->query('SELECT r.*,s.name,s.class_name,m.title material_title FROM recommendations r JOIN students s ON s.id=r.student_id LEFT JOIN learning_materials m ON m.id=r.material_id ORDER BY r.id DESC')->fetchAll();render('recommendations/index',compact('recommendations'));exit;}
if($page==='materials'){$materials=$pdo->query('SELECT m.*,s.name subject_name FROM learning_materials m LEFT JOIN subjects s ON s.id=m.subject_id ORDER BY m.id DESC')->fetchAll();render('materials/index',compact('materials'));exit;}
if($page==='classes'||$page==='subjects'){$type=$page;$title=$page==='classes'?'Data Kelas':'Data Mata Pelajaran';$items=$page==='classes'?$pdo->query('SELECT * FROM classes ORDER BY name')->fetchAll():$pdo->query('SELECT * FROM subjects ORDER BY name')->fetchAll();render('master/index',compact('items','title','type'));exit;}
if($page==='profile'){$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM students WHERE id=?');$q->execute([$id]);$student=$q->fetch();$q=$pdo->prepare('SELECT a.*,(a.knowledge_score+a.skill_score)/2 avg_score,r.action_label FROM assessments a LEFT JOIN recommendations r ON r.assessment_id=a.id WHERE a.student_id=? ORDER BY a.assessment_date');$q->execute([$id]);$history=$q->fetchAll();$summary=['avg'=>array_sum(array_column($history,'avg_score'))/max(count($history),1),'recommendation'=>$history?end($history)['action_label']:null];render('students/profile',compact('student','history','summary'));exit;}
redirect('dashboard');
